const incoming = $input.first().json;
let plan = incoming.body ?? incoming;
if (Array.isArray(plan) && plan.length === 1) plan = plan[0];
if (!plan || typeof plan !== 'object' || Array.isArray(plan)) {
  throw new Error('Webhook body must contain one research-plan JSON object');
}
return [{ json: plan }];

// n8n Code node: Run Once for All Items.
const plan = $input.first().json;
if (!plan.campaign_id || !Array.isArray(plan.queries) || plan.queries.length === 0) {
  throw new Error('Research plan requires campaign_id and a non-empty queries array');
}
const maximumCandidates = Number(plan.stop_conditions?.maximum_candidates ?? 200);
const supported = new Set(['google_maps', 'google_maps_scraper', 'b2b_tn', 'web_search']);

return plan.queries.map((query) => {
  if (!supported.has(query.source_id)) {
    throw new Error(`Unsupported discovery source: ${query.source_id}`);
  }
  return {
    json: {
      ...query,
      campaign_id: plan.campaign_id,
      maximum_candidates: maximumCandidates,
      limit_per_query: Math.max(1, Math.min(20, maximumCandidates)),
    },
  };
});

// n8n Code node: Run Once for Each Item.
const expected = $('Expand Discovery Queries').item.json;
const value = $json;

for (const field of ['campaign_id', 'query_id', 'source_id', 'status']) {
  if (typeof value[field] !== 'string' || !value[field]) {
    throw new Error(`Invalid discovery response: ${field}`);
  }
}
for (const field of ['campaign_id', 'query_id', 'source_id']) {
  if (value[field] !== expected[field]) {
    throw new Error(`Discovery connector changed controlled field: ${field}`);
  }
}
if (!['COMPLETED', 'SKIPPED'].includes(value.status)) {
  throw new Error(`Invalid discovery status: ${value.status}`);
}
if (!Array.isArray(value.candidates) || !Array.isArray(value.warnings)) {
  throw new Error('Discovery response requires candidates and warnings arrays');
}
for (const candidate of value.candidates) {
  for (const field of [
    'source_record_id', 'campaign_id', 'query_id', 'source_name',
    'source_type', 'source_url', 'retrieved_at', 'checksum',
  ]) {
    if (typeof candidate[field] !== 'string' || !candidate[field]) {
      throw new Error(`Invalid raw-source envelope field: ${field}`);
    }
  }
  if (!candidate.payload || typeof candidate.payload !== 'object') {
    throw new Error('Raw-source envelope payload must be an object');
  }
}

return { json: value };

// n8n Code node: Run Once for All Items.
const responses = $input.all().map((item) => item.json);
const firstTask = $('Expand Discovery Queries').all()[0].json;
const maximumCandidates = firstTask.maximum_candidates;
const allCandidates = responses.flatMap((response) => response.candidates);
const rawCandidates = allCandidates.slice(0, maximumCandidates);
const warnings = responses.flatMap((response) => response.warnings);
if (allCandidates.length > maximumCandidates) {
  warnings.push(`Candidate limit applied: ${allCandidates.length} reduced to ${maximumCandidates}`);
}
const completed = responses.filter((response) => response.status === 'COMPLETED').length;
const skipped = responses.filter((response) => response.status === 'SKIPPED').length;

return [{
  json: {
    contract_version: '1.0',
    campaign_id: firstTask.campaign_id,
    status: skipped === 0 ? 'COMPLETED' : (completed > 0 ? 'PARTIAL' : 'SKIPPED'),
    queries_attempted: responses.length,
    queries_completed: completed,
    queries_skipped: skipped,
    raw_candidate_count: rawCandidates.length,
    raw_candidates: rawCandidates,
    warnings,
  },
}];
